parameters.jsCode:
// w2w03c-enrich
// Build canonical context shape used by mint node + handler.
// Detect chosen_worker from existing labels. Synthesize trace_id.
const data = $input.item.json;
const inner = (data && data.data) || {};
const issue = inner.issue || {};
const labelNodes = (issue.labels && issue.labels.nodes) || [];
const lookupNodes = (inner.issueLabels && inner.issueLabels.nodes) || [];

const labels_map = {};
for (const l of lookupNodes) labels_map[l.name] = l.id;

const issue_existing_label_ids = labelNodes.map(l => l.id);
const issue_existing_label_names = labelNodes.map(l => l.name);

const WORKER_NAMES = ['claude-code','codex','cursor','gemini'];
const chosen_worker = issue_existing_label_names.find(n => WORKER_NAMES.includes(n)) || null;

const trace_id = 'watchdog-' + (issue.id || 'unknown') + '-' + Date.now().toString(36);

return { json: {
  issue_id: issue.id,
  issue_identifier: issue.identifier,
  issue_title: issue.title,
  trace_id,
  chosen_worker,
  confidence: null,
  risk: null,
  shadow_mode: false,
  button_set: 'watchdog',
  labels_map,
  issue_existing_label_ids
}};

// w2w03d-mint-callback-token
// Mint per-button HMAC, write 'intent' row to pending_callbacks.jsonl,
// build full Telegram sendMessage body (2-button watchdog set: Override + Triage).
// ANCHOR MUST match w7004-hmac-validate (2026-01-01T00:00:00Z = unix 1767225600).
// parse_mode=HTML so arbitrary issue_title content is safe.
const fs = require('fs');
const crypto = require('crypto');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const ANCHOR_UNIX = 1767225600;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const data = $input.item.json;
const secret = $env.TELEGRAM_CALLBACK_SECRET;
const chatId = $env.TELEGRAM_CHAT_ID;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');
if (!chatId) throw new Error('TELEGRAM_CHAT_ID not set');

const token = crypto.randomBytes(8).toString('hex').slice(0, 12);
const ts_minutes = Math.floor((Math.floor(Date.now()/1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);

function buttonFor(actionCode, label) {
  const nonce = crypto.randomBytes(4).toString('hex');
  const payload = token + actionCode + nonce + ts_hex;
  const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
  const cb = token + actionCode + nonce + ts_hex + hmac;
  if (cb.length !== 61) throw new Error('callback_data length mismatch: ' + cb.length);
  return { text: label, callback_data: cb };
}

const button_set = 'watchdog';
const buttons = [buttonFor('o','Override'), buttonFor('t','Triage')];
const inline_keyboard = [buttons];

const intentRow = {
  kind: 'intent',
  token,
  intent_written_at: new Date().toISOString(),
  trace_id: data.trace_id,
  issue_id: data.issue_id,
  issue_identifier: data.issue_identifier,
  chosen_worker: data.chosen_worker,
  confidence: data.confidence,
  risk: data.risk,
  button_set,
  issue_existing_label_ids: data.issue_existing_label_ids || [],
  labels_map: data.labels_map || {}
};
fs.appendFileSync(PENDING, JSON.stringify(intentRow) + '\n');

const identSafe = esc(data.issue_identifier || data.issue_id || '');
const titleSafe = esc(data.issue_title || '');
const traceSafe = esc(data.trace_id);
const linearUrl = data.issue_identifier ? ('https://linear.app/project-miru/issue/' + encodeURIComponent(data.issue_identifier)) : null;
const text = '<b>W2 pending-approval stale: ' + identSafe + '</b>\n'
  + titleSafe + '\n\n'
  + 'Pending-approval &gt; 24h. Override or apply triage.\n'
  + (linearUrl ? ('<a href="' + linearUrl + '">Open in Linear</a>\n') : '')
  + '\ntrace_id: ' + traceSafe;

const telegram_send_body = {
  chat_id: chatId,
  text,
  parse_mode: 'HTML',
  reply_markup: { inline_keyboard }
};

return { json: { ...data, callback_token: token, telegram_send_body } };
